CREATE TABLE IF NOT EXISTS "LivestockMovement" ("id" TEXT PRIMARY KEY,"tenantId" TEXT NOT NULL REFERENCES "Tenant"("id") ON DELETE RESTRICT,"fromFarmId" TEXT NOT NULL REFERENCES "Farm"("id") ON DELETE RESTRICT,"toFarmId" TEXT NOT NULL REFERENCES "Farm"("id") ON DELETE RESTRICT,"fromAreaId" TEXT,"toAreaId" TEXT,"movementDate" TIMESTAMP(3) NOT NULL,"reason" TEXT NOT NULL,"notes" TEXT,"actorUserId" TEXT NOT NULL,"requestKey" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Movement_destination_check" CHECK ("fromFarmId" <> "toFarmId" OR "fromAreaId" IS DISTINCT FROM "toAreaId"));
CREATE UNIQUE INDEX IF NOT EXISTS "LivestockMovement_tenantId_requestKey_key" ON "LivestockMovement"("tenantId","requestKey");
CREATE INDEX IF NOT EXISTS "LivestockMovement_tenantId_fromFarmId_movementDate_idx" ON "LivestockMovement"("tenantId","fromFarmId","movementDate");
CREATE INDEX IF NOT EXISTS "LivestockMovement_tenantId_toFarmId_movementDate_idx" ON "LivestockMovement"("tenantId","toFarmId","movementDate");
CREATE TABLE IF NOT EXISTS "LivestockMovementItem" ("id" TEXT PRIMARY KEY,"tenantId" TEXT NOT NULL,"movementId" TEXT NOT NULL REFERENCES "LivestockMovement"("id") ON DELETE RESTRICT,"animalId" TEXT NOT NULL REFERENCES "Animal"("id") ON DELETE RESTRICT,"codeSnapshot" TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS "LivestockMovementItem_movementId_animalId_key" ON "LivestockMovementItem"("movementId","animalId");
CREATE INDEX IF NOT EXISTS "LivestockMovementItem_tenantId_animalId_idx" ON "LivestockMovementItem"("tenantId","animalId");